            socket.write_all(response.as_bytes()).await.unwrap();
            if n == 1 {
                assert!(String::from_utf8_lossy(&request).contains("tool_call_id"));
                assert!(String::from_utf8_lossy(&request).contains("call-1"));
                assert!(String::from_utf8_lossy(&request).contains("call-2"));
            }
        }
    });
